from __future__ import annotations

import csv
from typing import IO

from secretscan.model import Finding, RunMeta

_FIELDS = [
    "fingerprint", "rule_id", "description", "severity", "confidence",
    "module", "file_path", "location", "redacted_value", "redacted_context",
    "secret_hash", "tags", "placeholder", "file_identity",
]


def render_csv(w: IO[str], findings: list[Finding], meta: RunMeta) -> None:
    writer = csv.DictWriter(w, fieldnames=_FIELDS)
    writer.writeheader()
    for f in findings:
        d = f.to_dict()
        row = {}
        for field in _FIELDS:
            val = d.get(field, "")
            if isinstance(val, list):
                val = ", ".join(str(v) for v in val)
            row[field] = val
        writer.writerow(row)
